local CHAT_WORDS={Chat="Чат",["Chat tab"]="Вкладка чата",["Action"]="Кнопка",["Player aura"]="Эффект",["Aura"]="Эффект",["Target debuff"]="Дебафф",["Debuff"]="Дебафф"}
function nfUIEdit.L(text)
    if type(text)~="string" then return text end
    if nfUIEdit.IsRussian() then
        if RU[text] then return RU[text] end
        -- Numbered panels, such as chat frames.
        local _,_,word,number=string.find(text,"^(%a[%a ]*) (%d+)$")
        if word and CHAT_WORDS[word] then return CHAT_WORDS[word].." "..number end
        return text
    end
    return text
end
